package com.bank.audit;

import java.util.Objects;
import java.util.logging.Logger;

// Compares two hierarchies for exact structural and value equality.
public class HierarchyComparatorService {

    private static final Logger log = Logger.getLogger(HierarchyComparatorService.class.getName());

    public boolean isSameTree(RoleNode a, RoleNode b) {
        // Both empty at this position → match.
        if (a == null && b == null) {
            return true;
        }
        // Exactly one empty → structural mismatch.
        if (a == null || b == null) {
            return false;
        }
        // Values must match (use .equals for objects).
        if (!Objects.equals(a.getRole(), b.getRole())) {
            return false;
        }
        // Both subtrees must also match (short-circuits on first diff).
        return isSameTree(a.getLeft(), b.getLeft())
                && isSameTree(a.getRight(), b.getRight());
    }

    public boolean audit(RoleNode headOffice, RoleNode branch) {
        boolean same = isSameTree(headOffice, branch);
        if (same) {
            log.info("Hierarchies MATCH — audit passed");
        } else {
            log.severe("Hierarchies DIFFER — audit FAILED, investigate");
        }
        return same;
    }
}
