package com.bank.audit;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class SameTreeDemo {

    private static final Logger log = Logger.getLogger(SameTreeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static RoleNode buildHierarchy(String rightLeafRole) {
        RoleNode manager = new RoleNode("BranchManager");
        RoleNode credit = new RoleNode("CreditOfficer");
        RoleNode risk = new RoleNode(rightLeafRole);
        manager.setLeft(credit);
        manager.setRight(risk);
        return manager;
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Hierarchy Audit (Same Tree)");
        HierarchyComparatorService service = new HierarchyComparatorService();

        RoleNode headOffice = buildHierarchy("RiskHead");
        RoleNode branchMatch = buildHierarchy("RiskHead");
        RoleNode branchDiff  = buildHierarchy("UnknownApprover"); // injected role

        service.audit(headOffice, branchMatch); // MATCH
        service.audit(headOffice, branchDiff);  // DIFFER
    }
}
